-- Hidden alternative honeymoon plans, visible only to profiles that have been granted access.
-- Content lives in the database (not in the public JS bundle) and is protected by RLS.

create table feature_access (
  profile_id uuid not null references profiles (id) on delete cascade,
  feature text not null,
  created_at timestamptz not null default now(),
  primary key (profile_id, feature)
);

-- Each person can see only their own grants. Grants are written by the service role / SQL, never by the app.
alter table feature_access enable row level security;

create policy "feature_access: read own" on feature_access
  for select to authenticated
  using (profile_id = auth.uid());

create table trip_alternatives (
  key text primary key,
  label text not null,
  data jsonb not null,
  updated_at timestamptz not null default now()
);

-- A plan is readable only if the signed-in person has been granted access to the feature with the same key.
alter table trip_alternatives enable row level security;

create policy "trip_alternatives: read if granted" on trip_alternatives
  for select to authenticated
  using (
    exists (
      select 1 from feature_access fa
      where fa.profile_id = auth.uid() and fa.feature = trip_alternatives.key
    )
  );

create trigger trip_alternatives_set_updated_at
  before update on trip_alternatives
  for each row execute function set_updated_at();

